from pathlib import Path
Import("env")
root = Path(env.subst("$PROJECT_DIR"))
def _cpp_define_names():
    names = set()
    for value in env.get("CPPDEFINES", []):
        if isinstance(value, (tuple, list)):
            value = value[0]
        value = str(value)
        if value.startswith("-D"):
            value = value[2:]
        names.add(value.split("=", 1)[0])
    return names

# The normal page is shared by production and test builds.  Only the named
# simulated-racing test environment receives the developer drawer and keyboard
# passage controls; production builds contain neither the controls nor their
# Browser-side handlers.
simulated_racing_ui = "PP_SIMULATED_RACING_TEST" in _cpp_define_names()
html_source = root / "browser" / "normal_browser.html"
page_inc = root / "include" / "pp" / "normal_browser_page.inc"
html = html_source.read_text(encoding="utf-8")
# Older checked-in Browser copies contain a small set of double-encoded
# punctuation glyphs (for example ``â€¦``).  Repair those presentation bytes
# in the generation input so semantic transformations remain stable across
# source copies; this does not change Browser authority or behaviour.
html = (html
        .replace("\u00e2\u20ac\u00a6", "…")
        .replace("\u00e2\u20ac\u201d", "—")
        .replace("\u00e2\u20ac\u00ba", "›")
        .replace("\u00c2\u00b7", "·"))
# Track Setup is kept as a small source-side extension so the minified
# checked-in page stays reviewable.  Fold that extension into the existing
# production script before applying the normal Browser integration passes;
# the embedded payload therefore remains one syntactically valid script.
track_script_start = html.find("\n<script>(function(){let trackSetupData=")
if track_script_start >= 0:
    track_script_end = html.find("</script>", track_script_start)
    if track_script_end < 0:
        raise RuntimeError("Track Setup Browser extension is missing its script terminator")
    track_script = html[track_script_start + len("\n<script>"):track_script_end]
    html_without_track_script = html[:track_script_start] + html[track_script_end + len("</script>"):]
    first_script_close = html_without_track_script.find("</script>")
    if first_script_close < 0 or first_script_close >= track_script_start:
        raise RuntimeError("Track Setup Browser extension has no primary script anchor")
    html = (html_without_track_script[:first_script_close] + track_script +
            html_without_track_script[first_script_close:])
if ')PPHTML"' in html:
    raise RuntimeError("normal_browser.html contains the raw-string terminator")

def replace_once(old, new, label):
    global html
    old_count = html.count(old)
    if old_count == 1:
        html = html.replace(old, new, 1)
        return
    # Some accepted presentation corrections are already present in the
    # checked-in source. Treat that as idempotent rather than attempting to
    # apply the same transformation twice.
    if html.count(new) == 1:
        return
    raise RuntimeError(f"normal Browser integration anchor {label} expected once or already applied, found old={old_count} new={html.count(new)}")

def replace_in_function(start, end, old, new, expected, label):
    global html
    a = html.find(start)
    b = html.find(end, a + len(start))
    if a < 0 or b < 0:
        raise RuntimeError(f"normal Browser integration function boundary {label} not found")
    section = html[a:b]
    count = section.count(old)
    if count != expected:
        if section.count(new) == expected:
            return
        raise RuntimeError(f"normal Browser integration anchor {label} expected {expected} or already applied, found old={count} new={section.count(new)}")
    section = section.replace(old, new)
    html = html[:a] + section + html[b:]

def inject_before_first_script_close(fragment, label):
    global html
    marker = "</script>"
    index = html.find(marker)
    if index < 0:
        raise RuntimeError(f"normal Browser integration anchor {label} not found")
    html = html[:index] + fragment + html[index:]

def inject_before_first_script_open(fragment, label):
    global html
    marker = "<script>"
    index = html.find(marker)
    if index < 0:
        raise RuntimeError(f"normal Browser integration anchor {label} not found")
    html = html[:index] + fragment + html[index:]

