racer_selection_js = r'''let racerSetupData=null,racerSetupLoading=false;
async function loadRacerSetup(){if(racerSetupLoading)return;racerSetupLoading=true;try{racerSetupData=await G('/racers')}catch(_){racerSetupData={error:true}}finally{racerSetupLoading=false;if(V==='racers'||V==='setup')render()}}
function racerEscape(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function racerOptions(selected,other){if(!racerSetupData||!Array.isArray(racerSetupData.racers))return '<option>Racers unavailable</option>';const ordinary=racerSetupData.racers.map(r=>{const id=Number(r.id||0),duplicate=id===other&&id!==selected;return `<option value="${id}" ${id===selected?'selected':''} ${duplicate?'disabled':''}>${racerEscape(r.name||`MUG ${id}`)}${duplicate?' · assigned to other lane':''}</option>`}).join('');const remembered=(racerSetupData.assignments||[]).find(a=>Number(a.mugId)===Number(selected));if(remembered&&!remembered.selectable)return `<option value="${selected}" selected disabled>${racerEscape(remembered.name||`MUG ${selected}`)} · reconcile</option>${ordinary}`;return ordinary}
async function submitRacerSelection(){const canEdit=!!(C?.isMaster===true&&S?.lifecycle==='READY');if(!canEdit){note('Racers can be assigned by the controlling Race Director while P&P is READY.');return}const lane1=Number($('#racerLane1')?.value||0),lane2=Number($('#racerLane2')?.value||0);if(!lane1||!lane2||lane1===lane2){note('Choose two different racers.');return}const id=corr++,traceId=diagnosticTraceId();diagnosticAction('SETUP',id,traceId);try{const r=await fetch('/request/setup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({correlationId:id,diagnosticTraceId:traceId,mode:P?.mode||'LAP_RACE',lapTarget:Number(P?.lapTarget||1),durationMinutes:Number(P?.durationMinutes||0),finishPolicy:fp(P?.finishBehaviour),proposalRevision:Number(P?.proposalRevision||0),racerAssignmentMask:3,lane1MugId:lane1,lane2MugId:lane2})});if(r.status!==202){note('P&P rejected the racer assignment.');return}await wait(id);racerSetupData=null;await poll('reconnect')}catch(_){note('Racer assignment could not be completed.')}}
async function createNamedMug(){if(!C?.isMaster||S?.lifecycle!=='READY'){note('Only the controlling Race Director can create a MUG while P&P is READY.');return}if(racerCreationBusy)return;const name=String($('#newMugName')?.value||'');if(!name){note('Enter a MUG name from 1 to 40 characters.');return}racerCreationBusy=true;try{const response=await fetch('/request/mug/create',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});let body={};try{body=await response.json()}catch(_){}if(!response.ok||body.accepted!==true){const reason=body.result||'CREATE_FAILED';note(reason==='INVALID_NAME'?'Use a valid UTF-8 name from 1 to 40 characters.':reason==='CAPACITY_FULL'?'The saved MUG limit has been reached.':reason==='STORAGE_UNAVAILABLE'?'Storage is unavailable; the MUG was not saved.':'P&P could not create that MUG.');return}note(`MUG ${body.id} created.`);racerSetupData=null;await loadRacerSetup()}catch(_){note('P&P could not create that MUG.')}finally{racerCreationBusy=false;if(V==='racers'||V==='setup')render()}}
function racerControls(){const canEdit=!!(C?.isMaster===true&&S?.lifecycle==='READY'),a=(racerSetupData?.assignments||[]),lane1=a.find(x=>Number(x.lane)===1),lane2=a.find(x=>Number(x.lane)===2),selected1=Number(lane1?.mugId||P?.entries?.[0]?.mugId||0),selected2=Number(lane2?.mugId||P?.entries?.[1]?.mugId||0);if(!racerSetupData||racerSetupData.error)return '<p class="muted">Racer information is unavailable.</p>';const reconciliation=a.some(x=>x.reconciliationRequired);return `<div class="racer-selection">${reconciliation?'<p class="muted">A remembered racer is unavailable. Choose a replacement before starting.</p>':''}<div class="form"><label for="racerLane1">Lane 1 racer</label><select id="racerLane1" ${canEdit?'':'disabled'}>${racerOptions(selected1,selected2)}</select></div><div class="form"><label for="racerLane2">Lane 2 racer</label><select id="racerLane2" ${canEdit?'':'disabled'}>${racerOptions(selected2,selected1)}</select></div><button id="applyRacers" class="btn primary" ${canEdit?'':'disabled'}>Apply racers</button><div class="form"><label for="newMugName">New MUG name</label><input id="newMugName" maxlength="40" ${canEdit?'':'disabled'} placeholder="1–40 characters"></div><button id="createMug" class="btn" ${canEdit?'':'disabled'}>Create named MUG</button><p class="muted">MUG 1 and MUG 2 are built-in anonymous choices. Saved names and permanent IDs are controller-owned.</p></div>`}
function bindRacerControls(){if($('#applyRacers'))$('#applyRacers').onclick=submitRacerSelection;if($('#createMug'))$('#createMug').onclick=createNamedMug}
const baseSetupWithRacers=setup;setup=function(){baseSetupWithRacers();const host=document.querySelector('.entries');if(host){host.innerHTML=racerControls();bindRacerControls();if(!racerSetupData&&!racerSetupLoading)loadRacerSetup();}else loadRacerSetup()};
function racerSetupView(){if(!racerSetupData){A.innerHTML='<section class="hero"><div class="eye">RACE SETUP</div><h1>Racers</h1><p class="muted">Reading saved racer identities…</p></section>';loadRacerSetup();return}A.innerHTML=`<section class="hero"><div class="eye">RACE SETUP</div><h1>Racers</h1><p class="muted">Assign existing racer identities to the two physical lanes.</p></section><section class="card"><h2>Race entries</h2>${racerControls()}<div class="actions"><button class="btn" id="racerBack">BACK TO RACE SETUP</button></div></section>`;bindRacerControls();$('#racerBack').onclick=()=>{V='setup';viewPinned=true;render()}}
const baseRenderWithRacers=render;render=function(){if(V==='racers')return racerSetupView();return baseRenderWithRacers()};
let racerCreationBusy=false;if(V==='racers'||V==='setup')loadRacerSetup();'''
